package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.jobs.WorkerRecoveryTelemetry.*;
import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;
import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
class WorkerRecoveryMonitoringCycleTest {
 static final Key KEY=new Key("OPS-03","java","fictional-sole-worker");
 WorkerRecoveryMonitoringCycle cycle(OperationalPersistenceFixture f,Api api){var store=f.store();var value=new WorkerRecoveryMonitoringCycle(KEY,api,new WorkerRecoveryEvidence(),store,f.monitor(store),()->new OperationalMonitoringService.Configuration(1,MonitoringFixtures.complete()),f.clock);value.start();return value;}
 @Test void completeFactCommitsOncePerMinuteAndRestartSkipsProvider(){var f=new OperationalPersistenceFixture();var calls=new AtomicInteger();Api api=()->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return new Evidence(f.clock.now,new Snapshot(0,0,true),0,true);};assertEquals(WorkerRecoveryMonitoringCycle.Outcome.SAMPLED,cycle(f,api).tick());assertEquals(Status.NORMAL,f.store().read(KEY).status());assertEquals("0",f.store().read(KEY).observedValue());assertEquals(WorkerRecoveryMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle(f,api).tick());assertEquals(1,calls.get());}
 @Test void failedThresholdAndUnknownKeepGuardUntilCompleteConfiguredRecovery(){var f=new OperationalPersistenceFixture();assertEquals(WorkerRecoveryMonitoringCycle.Outcome.SAMPLED,cycle(f,()->new Evidence(f.clock.now,new Snapshot(90,1,false),3,false)).tick());assertEquals(java.util.Set.of(Guard.DISPATCH_AI),f.store().read(KEY).guards());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->null).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());assertEquals(java.util.Set.of(Guard.DISPATCH_AI),f.store().read(KEY).guards());for(int n=0;n<4;n++){f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->new Evidence(f.clock.now,new Snapshot(0,0,true),0,true)).tick();if(n<3)assertFalse(f.store().read(KEY).guards().isEmpty());}assertTrue(f.store().read(KEY).guards().isEmpty());}
 @Test void underThresholdStaleAndAcquisitionFailureRemainUnknown(){var f=new OperationalPersistenceFixture();cycle(f,()->new Evidence(f.clock.now,new Snapshot(0,1,false),1,false)).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->new Evidence(f.clock.now.minusSeconds(121),new Snapshot(0,0,true),0,true)).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->{throw new IllegalStateException("fictional unknown");}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());}
 @Test void stoppedAndCrossMinuteAcquisitionDoNotProduceLateHealthyState(){var f=new OperationalPersistenceFixture();var value=cycle(f,()->{f.clock.now=f.clock.now.plusSeconds(60);return new Evidence(f.clock.now,new Snapshot(0,0,true),0,true);});value.tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());value.stop();assertEquals(WorkerRecoveryMonitoringCycle.Outcome.STOPPED,value.tick());}
 @Test void singleFlightAndStopDuringProviderDoNotCommit()throws Exception{var f=new OperationalPersistenceFixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var value=cycle(f,()->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();}return new Evidence(f.clock.now,new Snapshot(0,0,true),0,true);});var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(value::tick);assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(WorkerRecoveryMonitoringCycle.Outcome.BUSY,value.tick());value.stop();release.countDown();assertEquals(WorkerRecoveryMonitoringCycle.Outcome.STOPPED,first.get(5,TimeUnit.SECONDS));assertNull(f.store().read(KEY));}finally{release.countDown();executor.shutdownNow();}}
}
